import java.util.*;
import java.io.*;

public class Main {
    // Return an array: the first m entries are the cab counts after each log,
    // the last entry is the timestamp when all users share one cab (or -1).
    static long[] track(int n, long[][] logs) {
        // Write your solution here
        long[] res = new long[logs.length + 1];
        res[logs.length] = -1;
        return res;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        long[][] logs = new long[m][3];
        for (int i = 0; i < m; i++) {
            for (int k = 0; k < 3; k++) {
                in.nextToken();
                logs[i][k] = (long) in.nval;
            }
        }
        long[] res = track(n, logs);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < m; i++) sb.append(res[i]).append(i + 1 < m ? " " : "");
        sb.append('\n').append(res[m]).append('\n');
        System.out.print(sb);
    }
}
